import type {Ajv} from 'ajv';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry schema compilation', () => {
  // specs/hal-engine-tool-input-validation/spec.md#7
  it('rejects an invalid static schema at registration', () => {
    const registry = new ToolRegistry();
    expect(() =>
      registry.register(
        {name: 'weather', description: 'Weather', inputSchema: {type: 'not-a-type'}},
        async () => 'sunny'
      )
    ).toThrow(/weather/);
  });
});

// specs/hal-engine-tool-input-validation/spec.md#9
it('caches dynamic validators by schema object', async () => {
  const registry = new ToolRegistry();
  const first = {type: 'object'};
  const second = {type: 'object', required: ['location']};
  let schema = first;
  registry.register(
    () => ({name: 'dynamic', description: 'Dynamic', inputSchema: schema}),
    async () => 'ok'
  );
  const ajv = (registry as unknown as {ajv: Ajv}).ajv;
  const compile = jest.spyOn(ajv, 'compile');
  await registry.execute('dynamic', {});
  await registry.execute('dynamic', {});
  schema = second;
  await registry.execute('dynamic', {});
  expect(compile.mock.calls).toEqual([[first], [second]]);
});

// specs/hal-engine-tool-input-validation/spec.md#3
it('returns a rejection for a missing required property', async () => {
  const registry = new ToolRegistry();
  const execute = jest.fn(async () => 'sunny');
  registry.register(
    {name: 'weather', description: 'Weather', inputSchema: {type: 'object', required: ['location']}},
    execute
  );
  const response = await registry.execute('weather', {});
  expect({result: response.result, calls: execute.mock.calls.length}).toEqual({
    result: expect.stringMatching(/location.*required|required.*location/i),
    calls: 0,
  });
});
